    pub fn new() -> Self {
        EventBus { subscriptions: Vec::new(), next_id: 1 }
    }

    /// Returns the subscription's id, for `unsubscribe`.
    pub fn subscribe(&mut self, topic: &[u8], handler: Handler) -> i32 {
        let id = self.next_id;
        self.next_id += 1;
        self.subscriptions.push(Subscription { id, topic: topic.to_vec(), handler });
        id
    }

    /// False when no subscription has the id.
    pub fn unsubscribe(&mut self, id: i32) -> bool {
        match self.subscriptions.iter().position(|s| s.id == id) {
            Some(at) => {
                self.subscriptions.remove(at);
                true
            }
            None => false,
