    /// failure (the handlers after it don't run).
    pub fn publish(&self, event: &Event) -> Result<i32, HandlerFailed> {
        let mut called = 0;
        for s in &self.subscriptions {
            if s.topic == b"*" || s.topic == event.topic {
                (s.handler)(event)?;
                called += 1;
            }
        }
        Ok(called)
    }

    pub fn subscriptions(&self) -> usize {
        self.subscriptions.len()
    }
}

